{
  "name": "脚本编辑器",
  "name_en": "Script Editor",
  "manufacturer": "",
  "description": "用于实验控制软件中的脚本编辑与执行界面，可新建、打开、保存和运行脚本，常用于编写与调试实验自动化流程。",
  "description_en": "A script editing and execution interface used in laboratory control software. It is used to create, open, save, and run scripts for experiment automation and debugging.",
  "actions": [
    {
      "action_name": "auto-newFile",
      "description": "新建脚本文件。",
      "description_en": "Create a new script file."
    },
    {
      "action_name": "auto-openFile",
      "description": "打开已有脚本文件。",
      "description_en": "Open an existing script file."
    },
    {
      "action_name": "auto-saveFile",
      "description": "保存当前脚本文件。",
      "description_en": "Save the current script file."
    },
    {
      "action_name": "auto-saveAsFile",
      "description": "将当前脚本另存为新文件。",
      "description_en": "Save the current script as a new file."
    },
    {
      "action_name": "auto-runCurrentCode",
      "description": "运行当前编辑器中的代码。",
      "description_en": "Run the code in the current editor instance."
    },
    {
      "action_name": "auto-stopExecution",
      "description": "停止当前正在执行的脚本。",
      "description_en": "Stop the currently running script."
    },
    {
      "action_name": "auto-textChanged",
      "description": "通知编辑内容已发生变化。",
      "description_en": "Notify that the editor content has changed."
    },
    {
      "action_name": "auto-instanceCloseClicked",
      "description": "关闭指定的编辑器实例。",
      "description_en": "Close the specified editor instance."
    },
    {
      "action_name": "auto-verifyNotUnsaved",
      "description": "检查指定编辑器实例是否存在未保存内容。",
      "description_en": "Check whether the specified editor instance has unsaved changes."
    },
    {
      "action_name": "auto-getScriptName",
      "description": "获取指定编辑器实例的脚本名称。",
      "description_en": "Get the script name for the specified editor instance."
    },
    {
      "action_name": "auto-runScript",
      "description": "运行给定的脚本代码。",
      "description_en": "Run the provided script code."
    }
  ],
  "tag_hints": [
    "script editing",
    "code execution",
    "lab automation scripting",
    "file management",
    "experiment control GUI"
  ]
}

